+import { pool } from "./pool.ts";
+import { Client } from "pg";
+
+export interface NotificationListener {
+  onJobReady: () => void;
+  onError: (error: Error) => void;
+}
+
+export const subscribeToJobNotifications = async (
+  listener: NotificationListener,
+): Promise<() => Promise<void>> => {
+  const client = new Client({ connectionString: process.env.DATABASE_URL });
+  let unsubscribed = false;
+
+  try {
+    await client.connect();
+    await client.query("LISTEN \"jobs:ready\"");
+
+    client.on("notification", () => {
+      listener.onJobReady();
+    });
+
+    client.on("error", (error) => {
+      if (!unsubscribed) {
+        listener.onError(error);
+      }
+    });
+  } catch (error) {
+    listener.onError(error as Error);
+  }
+
+  return async () => {
+    unsubscribed = true;
+    await client.end();
+  };
+};
+
+export const claimNextJob = async (): Promise<{ id: string; payload: string } | null> => {
+  const result = await pool.query(
+    "SELECT id, payload FROM jobs WHERE status = 'ready' ORDER BY created_at LIMIT 1 FOR UPDATE SKIP LOCKED",
+  );
+  const row = result.rows[0];
+  if (row === undefined) return null;
+
+  await pool.query("UPDATE jobs SET status = 'claimed' WHERE id = $1", [row.id]);
+  return { id: row.id, payload: row.payload };
+};
+
+export const completeJob = async (jobId: string): Promise<boolean> => {
+  const result = await pool.query(
+    "UPDATE jobs SET status = 'completed' WHERE id = $1 AND status = 'claimed' RETURNING id",
+    [jobId],
+  );
+  return result.rows.length > 0;
+};
+
+export const notifyJobReady = async (): Promise<void> => {
+  await pool.query("NOTIFY \"jobs:ready\"");
+};
