+export interface JobConsumer {
+  poll: (ms?: number) => Promise<void>;
+}
+
+export const createJobConsumer = (
+  baseUrl: string,
+  handler: (payload: string) => Promise<void>,
+): JobConsumer => {
+  let running = false;
+
+  const processJob = async (): Promise<boolean> => {
+    try {
+      const response = await fetch(`${baseUrl}/api/jobs/next`);
+
+      if (response.status === 204) {
+        return false; // No job available
+      }
+
+      if (!response.ok) {
+        throw new Error(`HTTP error! status: ${response.status}`);
+      }
+
+      const job = await response.json();
+      await handler(job.payload);
+
+      // Mark job as complete
+      const completeResponse = await fetch(`${baseUrl}/api/jobs/${job.id}/complete`, {
+        method: "POST",
+      });
+
+      if (!completeResponse.ok) {
+        throw new Error(`Failed to complete job: ${completeResponse.status}`);
+      }
+
+      return true; // Job was processed
+    } catch (error) {
+      console.error("Error processing job:", error);
+      return false;
+    }
+  };
+
+  return {
+    poll: async (delayMs = 1000) => {
+      running = true;
+      while (running) {
+        const processed = await processJob();
+        if (!processed) {
+          await new Promise((resolve) => setTimeout(resolve, delayMs));
+        }
+      }
+    },
+  };
+};
