+import http from "http";
+import { claimNextJob, completeJob } from "./notifications-api.ts";
+
+interface Route {
+  method: string;
+  path: string;
+  handler: (req: http.IncomingMessage, res: http.ServerResponse) => Promise<void>;
+}
+
+const routes: Route[] = [
+  {
+    method: "GET",
+    path: "/api/jobs/next",
+    handler: async (_req, res) => {
+      try {
+        const job = await claimNextJob();
+        if (job === null) {
+          res.writeHead(204); // No Content
+          res.end();
+        } else {
+          res.writeHead(200, { "Content-Type": "application/json" });
+          res.end(JSON.stringify(job));
+        }
+      } catch (error) {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Internal server error" }));
+      }
+    },
+  },
+  {
+    method: "POST",
+    path: "/api/jobs/:id/complete",
+    handler: async (req, res) => {
+      try {
+        const id = req.url?.split("/")[3];
+        if (!id) {
+          res.writeHead(400, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ error: "Invalid job ID" }));
+          return;
+        }
+
+        const success = await completeJob(id);
+        if (success) {
+          res.writeHead(200, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ success: true }));
+        } else {
+          res.writeHead(404, { "Content-Type": "application/json" });
+          res.end(JSON.stringify({ error: "Job not found or not claimed" }));
+        }
+      } catch (error) {
+        res.writeHead(500, { "Content-Type": "application/json" });
+        res.end(JSON.stringify({ error: "Internal server error" }));
+      }
+    },
+  },
+];
+
+export const startServer = (port: number): http.Server => {
+  const server = http.createServer(async (req, res) => {
+    for (const route of routes) {
+      const pathPattern = route.path.replace(/:id/, "[^/]+");
+      const pathRegex = new RegExp(`^${pathPattern}$`);
+
+      if (req.method === route.method && pathRegex.test(req.url || "")) {
+        await route.handler(req, res);
+        return;
+      }
+    }
+
+    res.writeHead(404, { "Content-Type": "application/json" });
+    res.end(JSON.stringify({ error: "Not found" }));
+  });
+
+  server.listen(port, () => {
+    console.log(`Notifications API listening on port ${port}`);
+  });
+
+  return server;
+};
